content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体的合法存续性与履约适格性",
            "check_points": [
                "通过国家企业信用信息公示系统或司法大数据平台核查该主体是否存在未结重大涉诉、被执行、失信、破产重整等风险信息",
                "核对营业执照登记的经营范围，确认合同项下标的（如软件采购）属于其核准经营范围内",
                "逐项比对合同载明的主体信息（联系地址、电话、传真、法定代表人/负责人、联系人）与最新工商登记信息是否完全一致",
                "如涉及软件等技术产品采购，核查卖方是否拥有该产品核心知识产权（如著作权登记证书、专利证书、授权链文件）或合法转授权证明"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保合同核心条款结构完整、要素齐备、逻辑闭环",
            "check_points": [
                "检查是否完整涵盖以下14类必备条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用约定、产品质量保证/服务标准、交付方式与地点、验收标准与程序、完成时限（含里程碑）、违约责任（含违约金计算方式）、司法管辖（明确法院或仲裁机构）、不可抗力定义及处理机制、廉洁承诺条款、合同变更程序、合同份数及效力说明、电子送达效力约定",
                "确认合同中已明确指定主要项目负责人，并完整记载其姓名、身份证号码及有效联系电话",
                "采购内容须具体列明品种、规格、型号、等级、花色等技术参数；若内容复杂，应以经双方签章的附件形式固化，并在正文引用该附件名称及编号"
            ]
        },
        {
            "id": "C3",
            "section": "合同金额与付款条款审查",
            "criterion": "保障价款约定清晰、支付节奏合理、财税合规",
            "check_points": [
                "合同金额须同时载明大小写，且二者完全一致；明确计量单位、单价、数量、总价、币种（如人民币/USD），禁止使用‘约’‘暂定’等模糊表述",
                "付款计划须设置可验证的节点（如‘初验合格后5个工作日内’），并预留不低于合同总额5%—10%的尾款于免费维保期届满且无质量争议后支付",
                "明确每次付款前需开具的发票类型（增值税专用发票/普通发票）、税率、开票时间及交付方式"
            ]
        },
        {
            "id": "C4",
            "section": "合同期限与时间表述审查",
            "criterion": "消除期限歧义，确保时间计算标准唯一、可执行",
            "check_points": [
                "合同期限须以起止日期（YYYY-MM-DD）或明确周期（如‘自2025年1月1日起至2026年12月31日止’）方式载明",
                "凡涉及‘日’‘月’‘季度’等时间单位，必须明确定义为‘自然日’或‘工作日’、‘自然季度’或‘滚动季度’（例如：‘自起始日起满3个月之日的前一日’），禁用‘月底’‘季末’等模糊表述"
            ]
        },
        {
            "id": "C5",
            "section": "文本规范性与一致性审查",
            "criterion": "保障合同文本形式严谨、内容统一、法律援引有效",
            "check_points": [
                "全文通读排查错别字、标点误用、标题层级混乱（如‘二、’后直接接‘（三）’）、语句成分残缺或逻辑矛盾等基础性文字错误",
                "逐条比对正文与所有附件中相同事项的约定（如验收标准、交付时间、违约金比例），确保表述完全一致，无冲突或留白",
                "清除招标文件、谈判纪要、询价函等前置流程中使用的非合同用语（如‘投标单位’‘响应人’‘谈判小组’），统一替换为‘甲方’‘乙方’‘本合同’等法定称谓",
                "核验合同首部‘甲方/乙方’全称与签署页‘签订主体名称’完全一致（包括括号、空格、简称与全称混用等细节）",
                "核查所援引法律法规名称、条款序号是否准确有效（如《民法典》第584条而非已废止的《合同法》第113条）",
                "确认合同正文末尾独立成行标注‘以下为合同签署栏’或‘以下无正文’字样，且该行之后无任何实质性内容"
            ]
        }
    ]
}
